INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63963810', 63963810, 'analyze_legacy', 'Kota Banjarmasin', 'kabkota', 'Dinas Kesehatan Kota Banjarmasin', 'Pengecatan Gedung Dinas Kesehatan (Gedung Depan)', 'Pekerjaan Konstruksi', 'Pengadaan Langsung', 'Kalimantan Selatan, Banjarmasin (Kota)', 199920000, 'January 2026', 'APBD', 1, 1, '1 paket', 'Pelaksanaan pekerjaan pengecatan Gedung Dinas Kesehatan (Gedung Depan) meliputi seluruh rangkaian kegiatan persiapan, pelaksanaan, dan penyelesaian akhir untuk meningkatkan tampilan, perlindungan, dan kenyamanan bangunan sesuai kondisi eksisting. Pekerjaan persiapan meliputi pembersihan permukaan dinding, pengelupasan cat lama yang rusak atau mengelupas, perbaikan ringan retak rambut dan cacat permukaan, serta perlakuan awal lainnya agar permukaan siap dicat. Pekerjaan utama meliputi pengecatan dinding eksterior dan/atau interior gedung menggunakan bahan cat yang sesuai dengan standar mutu dan spesifikasi teknis, diaplikasikan dengan metode kerja yang tepat untuk menghasilkan lapisan cat yang merata, tahan lama, dan estetis. Pekerjaan penyelesaian meliputi pembersihan area kerja, pemeriksaan hasil pengecatan, perbaikan ulang pada bagian yang belum memenuhi mutu, serta penataan kembali area terdampak pekerjaan. Seluruh pelaksanaan pekerjaan wajib memperhatikan ketentuan keselamatan dan kesehatan kerja (K3), menjaga kebersihan lingkungan, serta meminimalkan gangguan terhadap aktivitas perkantoran selama pekerjaan berlangsung.', 'Pekerjaan pengecatan dinding eksterior dan/atau interior Gedung Dinas Kesehatan (Gedung Depan) sesuai kondisi eksisting, meliputi persiapan permukaan, aplikasi cat bermutu sesuai spesifikasi, penerapan K3, serta penyelesaian akhir.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 241504);
