INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64261668', 64261668, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'RSU PUSAT DR SOERADJI TIRTONEGORO', 'Pengendalian Serangga dan Binatang Pembawa Penyakit Tahun 2026', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Tengah, Klaten (Kab.)', 153175664, 'January 2026', 'APBN - BADAN LAYANAN UMUM (F)', 1, 1, '1 PAKET', 'Kegiatan pelaksanaan pekerjaan pengendalian serangga dan binatang pembawa penyakit di seluruh ruang perawatan dan perkantoran dengan Pekerjaan Monitoring pola investasi serangga dan quality control, upaya sebagai berikut : 1. Kunjungan/treatment/inspeksi pola investasi serangga setiap hari (6 hari kerrja); 2. Monitoring unit Fly Insect/Lalat SEdengan penggantian unit fly catcher secara berkala 3. Monitoring Pengendalian Rodent Control/Tikus dengan pemasangan Glue trap additional dan umpan baiting di semua area yang berpotensi munculnya hama tikus 4. Monitoring keberadaan Cockroach/Kecoa dengan spraying menggunakan bahan aktif; di runagan, area dapur, saluran, bak kontrol air limbah dll, 5. Monitoring keberadaan koloni semut dengan aplikasi Spraying dan baiting granule 6. Monitoring sweeping manual hama kucing di seluruh area rumah sakit ; 7. Monitoring keberadaan Mosquito/nyamuk di unit Mosquito trap dan dilakukan Spraying .pada area saluran air dengan Aplikasi hot fogging bahan aktif.sesuai persyaratan. 8. Membuat laporan harian kegiatan kepada Instalasi Kesehatan Lingkungan dan K3 melalui Grup WA.dan Laporan bulanan dengan rekomendasi perbaikan sarpras.', '1. Pihak ketiga yang memiliki pengalaman mengerjakan pest control di rumah sakit vertikal; 2. Calon petugas pest control yang diajukan sudah memiliki sertifikat dari Dinas Kesehatan/Assphami, minimal 2 orang; 3. Memiliki kantor cabang/kantor perwakilan dan struktur organisasi di cabang dimana lokasi RS masuk di dalam wilayah operasional cabang terkait; 4. Penyedia menyediakan sarana/peralatan pest control (contoh: perangkap tikus, kecoa, dan lain lain) di rumah sakit selama 24 jam. 5. Menyediakan APD pada petugas pelaksana dan alat yang mendukung upaya pengendalian dan pembasmian serangga dan binatang pembawa penyakit', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 241739);
