INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62886071', 62886071, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'LABORATORIUM LINGKUNGAN HIDUP DAERAH', 'Pemeliharaan Lift', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 82283130, 'February 2026', 'APBD', 1, 1, '1 paket', 'terselenggaranya pemeliharaan lift secara profesional dan berkesinambungan. di lingkungan kantor Laboratorium Lingkungan Hidup Daerah Provinsi Daerah Khusus Ibukota Jakarta', 'Ruang lingkup dari kegiatan ini adalah : Menyediakan tenaga kerja/teknis/mekanik untuk melaksanakan perawatan secara berkala selama 1 (satu) kali dalam satu bulan Menyediakan sarana pendukung untuk pekerjaan pembersihan di ruang mesin, shaft dan pit lift Menyediakan pelumasan, dan lubrikasi pada beberapa tempat lift Melaksanakan pengetesan dan penyetelan ulang terhadap system kerja lift secara periodik sesuai standar lift Melakukan pemantauan / monitoring / pengecekan secara berkala seluruh system lift antara lain : Perlengkapan keamanan / safety . Brakes dan switches Kontrol panel dan mesin lift Signal-signal, interphone dan lampu lift Kabel / wiring terminal dan contactor Emergency light dan exhaust fan, bila ada Tegangan dan frekuensi Listrik Melakukan Tindakan pencegahan / preventif bila ada tanda-tanda akan terjadi sesuatu yang bisa mengakibatkan timbulnya hal-hal yang tidak diinginkan Memberikan laporan dan catatan seperlunya secara tertulis secara berkala ke pihak pengelola gedung mengenai lift, yang diteruskan kepada pimpinan. Memberikan petunjuk dan sarana-sarna yang diperlukan untuk keamanan lift Melaporkan semua perlatan lift yang bersifat mekanik yang memerlukan penggantian spare part , overhaul, dan repair bila diperlukan Melaksanakan penggantian spare parts yang diperlukan atas unjuk dan persetujuan dari Laboratorium Lingkungan Hidup Daerah (LLHD) Emergency Call di hari kerja maupun di luar jam kerja Pekerjaan pemeliharaan Lift harus didokumentasikan dengan bukti foto dan catatan pemeliharaan yang dilakukan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 243595);
