INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62176897', 62176897, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA BATU LICIN', 'Biaya Jasa Layanan Pos Bantuan Hukum 1 Jam Layanan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Kalimantan Selatan, Tanah Bumbu (Kab.)', 50000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 500, ORANG, @ 100000 )', '1. Biaya Jasa Layanan Pos Bantuan Hukum 1 Jam Layanan ( 500, ORANG, @ 100000 );', 'Pekerjaan yang akan dilaksanakan oleh Konsultan Layanan Pos Bantuan Hukum seperti yang dimaksud pada KAK harus memperlihatkan persyaratan-persyaratan sebagai berikut: A. Syarat-syarat Lembaga Penyedia Jasa Hukum adalah: - Berbentuk Badan Hukum (dibuktikan dengan Akta Pendiriannya); - Berdomisili di wilayah Hukum Pengadilan Agama Batulicin atau terdapat perwakilan di wilayah Hukum Pengadilan Agama Batulicin; - Memiliki pengalaman dan menangani perkara dan/atau beracara di Pengadilan; - Memiliki minimal satu Advokat yang sudah disumpah (dibuktikan dengan Berita Acara Sumpah dan kartu anggota); - Memiliki staf atau anggota yang nantinya bertugas di POSBAKUM Pengadilan yang bergelar minimal Sarjana Hukum; - Lembaga sudah terakreditasi; - Telah mendaftar di LPSE Mahkamah Agung RI dan terintegrasi pada aplikasi SIKaP; B. Syarat petugas piket pada Posbakum: - Advokat atau petugas yang bergelas Sarjana Hukum; - Memiliki pengalaman minimal 1 (satu) tahun dalam pemberian Bantuan Hukum; - Memiliki integritas tinggi dalam membantu Pengadilan Agama untuk mewujudkan pelayanan hukum yang prima di Pengadilan; - Menguasai Hukum Acara. Persyaratan Teknis Lainnya Selain kriteria umum diatas, untuk pekerjaan Konsultan Layanan Pos Bantuan Hukum berlaku pula ketentuan-ketentuan seperti standar, pedoman dan peraturan yang berlaku antara lain: a. Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2018 tentang Pengadaan Barang/Jasa Pemerintah; b. Surat Edaran Direktur Jenderal Badan Peradilan Agama Nomor: 0508.a/DjA/HK.00/III/2014 Tentang Petunjuk Pelaksanaan Peraturan Mahkamah Agung RI Nomor 1 tahun 2014 tentang Pedoman Pemberian Layanan Hukum bagi masyarakat tidak mampu di Pengadilan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 249634);
